#include <memory>
#include <functional>
#include <string>
#include <vector>
#include <mutex>
#include <thread>
#include <chrono>
#include <queue>
#include <iostream>
#include <atomic>

namespace mobile_backend {

struct AuditEntry {
    std::string user_id;
    std::string action;
    std::string timestamp;
    std::string details;
};

class AuditLogger {
public:
    AuditLogger() : running_(true) {
        worker_ = std::thread([this]() { processLoop(); });
    }
    ~AuditLogger() {
        running_ = false;
        if (worker_.joinable()) worker_.join();
    }
    void enqueue(AuditEntry entry) {
        std::lock_guard<std::mutex> lock(mtx_);
        queue_.push(std::move(entry));
    }
private:
    void processLoop() {
        while (running_) {
            std::this_thread::sleep_for(std::chrono::milliseconds(50));
            std::lock_guard<std::mutex> lock(mtx_);
            while (!queue_.empty()) {
                auto& e = queue_.front();
                std::cout << "[AUDIT] " << e.user_id << ": " << e.action << std::endl;
                queue_.pop();
            }
        }
    }
    std::mutex mtx_;
    std::queue<AuditEntry> queue_;
    std::thread worker_;
    std::atomic<bool> running_;
};

class SessionContext {
public:
    SessionContext(const std::string& uid, AuditLogger* logger)
        : user_id_(uid), logger_(logger), request_count_(0) {}

    const std::string& userId() const { return user_id_; }
    AuditLogger* logger() const { return logger_; }
    int incrementRequests() { return ++request_count_; }
private:
    std::string user_id_;
    AuditLogger* logger_;
    int request_count_;
};

using AsyncCallback = std::function<void(int status_code, const std::string& body)>;

class RequestPipeline {
public:
    struct PendingOp {
        AsyncCallback callback;
        std::chrono::steady_clock::time_point deadline;
    };

    void submitAsync(AsyncCallback cb, std::chrono::milliseconds timeout) {
        std::lock_guard<std::mutex> lock(mtx_);
        pending_.push_back({std::move(cb),
            std::chrono::steady_clock::now() + timeout});
    }

    void processCompletions() {
        std::lock_guard<std::mutex> lock(mtx_);
        for (auto& op : pending_) {
            op.callback(200, "{\"result\": \"ok\"}");
        }
        pending_.clear();
    }

private:
    std::mutex mtx_;
    std::vector<PendingOp> pending_;
};

class ApiHandler {
public:
    ApiHandler(AuditLogger* logger) : logger_(logger) {}

    void handleUserAction(const std::string& user_id, const std::string& action,
                          RequestPipeline& pipeline) {
        auto ctx = std::make_shared<SessionContext>(user_id, logger_);

        // First stage: validate and log
        logger_->enqueue({user_id, "request_start", "now", action});
        ctx->incrementRequests();

        // Capture raw pointer for the nested callback's audit trail
        SessionContext* ctx_ptr = ctx.get();

        // Submit primary async operation
        pipeline.submitAsync(
            [ctx, this](int status, const std::string& body) {
                // Primary completion - ctx shared_ptr keeps it alive
                logger_->enqueue({ctx->userId(), "primary_complete", "now", body});

                // Schedule follow-up audit verification
                scheduleAuditVerification(ctx);
            },
            std::chrono::milliseconds(5000));

        // Submit secondary async operation - captures ctx_ptr
        // Developer assumes primary callback keeps ctx alive via shared_ptr
        // but if primary completes and scheduleAuditVerification doesn't
        // extend lifetime, this callback may dangle
        pipeline.submitAsync(
            [ctx_ptr, this](int status, const std::string& body) {
                // This uses raw pointer - relies on ctx still being alive
                // through the shared_ptr in the primary callback's capture
                std::string uid = ctx_ptr->userId();
                ctx_ptr->incrementRequests();
                logger_->enqueue({uid, "secondary_complete", "now", body});
            },
            std::chrono::milliseconds(10000));
    }

private:
    void scheduleAuditVerification(std::shared_ptr<SessionContext> ctx) {
        // In production this would schedule another async op
        // The shared_ptr goes out of scope here after logging
        logger_->enqueue({ctx->userId(), "audit_verified", "now", ""});
        // ctx refcount decremented when this function returns
    }

    AuditLogger* logger_;
};

// Demonstrates the issue: if processCompletions is called in stages
void simulatePartialCompletion(RequestPipeline& pipeline) {
    // In real system, completions arrive at different times
    // If primary callback's shared_ptr is the last reference,
    // and it completes before secondary, ctx_ptr dangles
    pipeline.processCompletions();
}

} // namespace mobile_backend

int main() {
    mobile_backend::AuditLogger logger;
    mobile_backend::RequestPipeline pipeline;
    mobile_backend::ApiHandler handler(&logger);

    handler.handleUserAction("user_123", "purchase", pipeline);

    // Both callbacks execute - in this simple case both fire together
    // But in production with separate completion queues, ordering matters
    mobile_backend::simulatePartialCompletion(pipeline);

    std::this_thread::sleep_for(std::chrono::milliseconds(200));
    return 0;
}
